def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    aggressive_count = 0
    weak_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 90:
                    aggressive_count += 1
                if bid <= 40:
                    weak_count += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    elif hp <= 6:
        urgency += 0.2

    if no_water >= 2:
        urgency += 0.9
    elif no_water >= 1:
        urgency += 0.45

    urgency += scarcity * 0.6

    if urgency >= 1.5:
        target = max(78.0, highest_prev + 2.0)
    elif urgency >= 0.9:
        target = max(52.0 + 18.0 * scarcity, min(highest_prev + 1.0, 88.0))
    else:
        if supply >= 22:
            target = 24.0 + 6.0 * (1.0 if avg_prev > 60 else 0.0)
        elif supply >= 19:
            target = 32.0 + 8.0 * scarcity
        else:
            target = 42.0 + 12.0 * scarcity

        if aggressive_count >= 2 and hp > 4 and no_water == 0:
            target = min(target, 34.0)

        if weak_count >= 2 and highest_prev < 50:
            target = max(target, highest_prev + 1.5)

    if day >= 8:
        target += 6.0
    if day >= 10:
        target += 8.0

    reserve_floor = 0.0
    if hp > 4 and no_water == 0:
        reserve_floor = DAILY_SALARY * 0.35

    affordable = max(0.0, budget - reserve_floor)
    if urgency >= 1.5:
        affordable = budget

    bid = min(target, affordable if affordable > 0 else budget)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, max(85.0, highest_prev + 3.0)))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from traces (immediate reaction only)
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Baseline from yesterday: surviving bids clustered ~100-112; use that as target.
    target = DAILY_SALARY * 0.6  # 54
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        lowest_prev_bid = min(yesterday_bids)
        # If someone previously bid aggressively, match slightly below to win.
        if highest_prev_bid >= DAILY_SALARY * 0.85:  # >= 76.5
            target = min(DAILY_SALARY * 0.95, highest_prev_bid * 0.98)
        else:
            # Otherwise, anchor to the upper-middle of observed bids.
            target = max(DAILY_SALARY * 0.55, (lowest_prev_bid + highest_prev_bid) * 0.5)

    # Adjust for supply: higher supply reduces need to overbid.
    # supply in [15,25]; map to aggressiveness.
    if supply <= float(MIN_SUPPLY):
        supply_factor = 1.10
    elif supply >= float(MAX_SUPPLY):
        supply_factor = 0.90
    else:
        # Linear between 15 and 25
        supply_factor = 1.10 - (supply - float(MIN_SUPPLY)) * (1.10 - 0.90) / (float(MAX_SUPPLY - MIN_SUPPLY))

    # Adjust for my HP/no-water streak: if I'm in danger, increase bid.
    danger_boost = 1.0
    if hp <= 2:
        danger_boost = 1.25
    elif hp <= 4:
        danger_boost = 1.15
    if no_water_days >= 2:
        danger_boost = max(danger_boost, 1.20)

    bid = target * supply_factor * danger_boost

    # Clamp to sensible bounds relative to budget.
    # Ensure at least some bid if budget allows.
    min_bid = min(budget, DAILY_SALARY * 0.25)
    max_bid = min(budget, DAILY_SALARY * 1.20)
    if bid < min_bid:
        bid = min_bid
    if bid > max_bid:
        bid = max_bid

    # Final safety: never exceed budget.
    bid = min(bid, budget)

    # If budget is extremely low, bid it all.
    if budget <= 1.0:
        return budget

    return float(bid)

